function ChipSelect<T extends string | number>({
  label,
  options,
  value,
  onChange,
}: {
  label: string;
  options: { value: T; label: string }[];
  value: T;
  onChange: (v: T) => void;
}) {
  return (
    <div className="admin-chips" role="group" aria-label={label}>
      {options.map((opt) => (
        <button
          key={String(opt.value)}
          type="button"
          className={
            value === opt.value ? 'admin-chip admin-chip--active' : 'admin-chip'
          }
          aria-pressed={value === opt.value}
          onClick={() => onChange(opt.value)}
        >
          {opt.label}
        </button>
      ))}
    </div>
  );
}

input.new_string:
function ChipSelect<T extends string | number>({
  label,
  options,
  value,
  onChange,
  scroll,
}: {
  label: string;
  options: { value: T; label: string }[];
  value: T;
  onChange: (v: T) => void;
  scroll?: boolean;
}) {
  return (
    <div
      className={scroll ? 'admin-chips admin-chips--scroll' : 'admin-chips'}
      role="group"
      aria-label={label}
    >
      {options.map((opt) => (
        <button
          key={String(opt.value)}
          type="button"
          className={
            value === opt.value ? 'admin-chip admin-chip--active' : 'admin-chip'
          }
          aria-pressed={value === opt.value}
          onClick={() => onChange(opt.value)}
        >
          {opt.label}
        </button>
      ))}
    </div>
  );
}

function CategoryChips({
  categories,
  value,
  onChange,
  includeAll,
  disabled,
  label = 'Category',
}: {
  categories: Category[];
  value: string;
  onChange: (categoryId: string) => void;
  includeAll?: boolean;
  disabled?: boolean;
  label?: string;
}) {
  return (
    <div
      className="admin-chips admin-chips--scroll admin-category-chips"
      role="group"
      aria-label={label}
    >
      {includeAll && (
        <button
          type="button"
          className={
            value === ''
              ? 'admin-chip admin-chip--active'
              : 'admin-chip'
          }
          aria-pressed={value === ''}
          disabled={disabled}
          onClick={() => onChange('')}
        >
          All categories
        </button>
      )}
      {categories.map((c) => (
        <button
          key={c.id}
          type="button"
          className={
            value === c.id
              ? 'admin-chip admin-chip--active admin-category-chip'
              : 'admin-chip admin-category-chip'
          }
          style={{ '--chip-accent': c.color } as React.CSSProperties}
          aria-pressed={value === c.id}
          disabled={disabled}
          onClick={() => onChange(c.id)}
        >
          <span className="admin-category-chip__icon" aria-hidden="true">
            {c.icon}
          </span>
          <span className="admin-category-chip__name">{c.name}</span>
        </button>
      ))}
    </div>
  );
}

